(()=>{"use strict";const PAGE_SIZE=32,GRID_ID="outfit-grid";let currentData=[],activeFilterCount=0,activeMatches=[],resizeTimer=0;const grid=()=>document.getElementById(GRID_ID);const all=()=>Array.isArray(window.outfits)?window.outfits:[];function savedIds(){return window.getSavedIds&&typeof window.getSavedIds==="function"?window.getSavedIds():new Set}function columns(){return matchMedia("(max-width: 768px)").matches?2:4}function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}function showToast(msg){let t=document.getElementById("ac-toast");if(!t){t=document.createElement("div");t.id="ac-toast";t.style.cssText="position:fixed;bottom:32px;left:50%;transform:translateX(-50%) translateY(20px);background:#111;border:1px solid #333;color:#f0ece4;font-family:Space Mono,monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;padding:12px 24px;opacity:0;transition:opacity .3s,transform .3s;pointer-events:none;white-space:nowrap;z-index:9998";document.body.appendChild(t)}t.textContent=msg;t.style.opacity="1";t.style.transform="translateX(-50%) translateY(0)";clearTimeout(t._t);t._t=setTimeout(()=>{t.style.opacity="0";t.style.transform="translateX(-50%) translateY(20px)"},2200)}window.showToast=showToast;function bindSave(btn,o,set){const on=set.has(o.id);btn.type="button";btn.dataset.outfitId=o.id;btn.dataset.outfitTag=o.tag;btn.className="btn-save-card"+(on?" saved":"");btn.textContent=on?"♥":"♡";btn.setAttribute("aria-label",on?`Bỏ lưu ${o.tag} khỏi Closet`:`Lưu ${o.tag} vào Closet`);btn.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();window.toggleSave&&window.toggleSave(o,btn)})}function card(o,priority,set){const article=document.createElement("article");article.className="outfit-card";article.dataset.outfitId=o.id;article.style.aspectRatio=`${o.width}/${o.height}`;const link=document.createElement("a");link.className="outfit-card-link";link.href=`/outfits/${o.slug}.html`;link.setAttribute("aria-label",`Xem chi tiết ${o.tag}: ${o.title}`);const picture=document.createElement("picture"),img=document.createElement("img");img.alt=`Outfit nữ cá tính ${o.tag} — ${o.title} (${o.category})`;img.width=o.width;img.height=o.height;img.loading=priority?"eager":"lazy";img.decoding="async";if(priority)img.fetchPriority="high";img.src=o.img;picture.appendChild(img);const overlay=document.createElement("div");overlay.className="outfit-overlay";overlay.innerHTML=`<span class="outfit-tag">XEM OUTFIT</span><div class="outfit-num">${o.tag}</div>`;link.append(picture,overlay);const save=document.createElement("button");bindSave(save,o,set);article.append(link,save);return article}function estimateAndReserve(data,n){const vw=document.documentElement.clientWidth||window.innerWidth||360,w=Math.max(1,(vw-2*(n+1))/n),heights=Array(n).fill(0);data.forEach((o,i)=>{let c=i<n?i:heights.indexOf(Math.min(...heights));heights[c]+=w*(o.height/o.width)+2});const g=grid();if(g)g.style.minHeight=`${Math.ceil(Math.max(...heights))}px`}function render(data){const g=grid();if(!g)return;currentData=Array.isArray(data)?data:[];if(!currentData.length){g.replaceChildren();g.style.minHeight="0";const empty=document.createElement("p");empty.className="ac-filter-empty";empty.textContent="Không có outfit khớp tất cả bộ lọc. Hãy bỏ bớt một lựa chọn.";g.appendChild(empty);g.setAttribute("aria-busy","false");return}const n=columns();estimateAndReserve(currentData,n);const set=savedIds(),cols=Array.from({length:n},()=>{const c=document.createElement("div");c.className="ac-masonry-column";return c}),heights=Array(n).fill(0);currentData.forEach((o,i)=>{const target=i<n?i:heights.indexOf(Math.min(...heights));cols[target].appendChild(card(o,i<n,set));heights[target]+=o.height/o.width});g.classList.add("ac-stable-masonry");g.replaceChildren(...cols);g.setAttribute("aria-busy","false");requestAnimationFrame(()=>{g.style.minHeight=""})}window.renderAll=render;function pageSize(){return Math.min(PAGE_SIZE,all().length)}function syncPool(){const sig=`home32-original-images-v1|${all().map(o=>o.id).join("|")}`;try{if(sessionStorage.getItem("ac_outfit_signature")!==sig){sessionStorage.removeItem("ac_pool");sessionStorage.removeItem("ac_last_batch");sessionStorage.removeItem("savedOutfitOrder");sessionStorage.setItem("ac_outfit_signature",sig)}}catch(e){}}function batch(first){const data=all(),ids=data.map(o=>o.id),size=pageSize();let pool=[];try{pool=first?shuffle(ids):JSON.parse(sessionStorage.getItem("ac_pool")||"[]")}catch(e){pool=[]}pool=Array.isArray(pool)?pool.filter(id=>ids.includes(id)):[];if(!pool.length)pool=shuffle(ids);const out=[];while(out.length<size&&ids.length){if(!pool.length)pool=shuffle(ids.filter(id=>!out.includes(id)));const id=pool.shift();if(id&&ids.includes(id)&&!out.includes(id))out.push(id)}try{sessionStorage.setItem("ac_pool",JSON.stringify(pool));sessionStorage.setItem("ac_last_batch",JSON.stringify(out));sessionStorage.setItem("savedOutfitOrder",JSON.stringify(out))}catch(e){}return out.map(id=>data.find(o=>o.id===id)).filter(Boolean)}function randomize(scroll=true){if(activeFilterCount){render(shuffle(activeMatches));const feed=document.getElementById("feed-end-copy");if(feed)feed.textContent=`Đã hiển thị ${activeMatches.length} outfit phù hợp.`}else render(batch(false));if(scroll)requestAnimationFrame(()=>grid()?.scrollIntoView({behavior:"smooth",block:"start"}));window.acTrack&&window.acTrack("reload_outfits",{filtered:!!activeFilterCount,result_count:activeFilterCount?activeMatches.length:pageSize()})}window.randomize=randomize;window.updateSaveButtons=()=>{const set=savedIds();document.querySelectorAll(".btn-save-card").forEach(btn=>{const id=btn.dataset.outfitId,on=set.has(id);btn.textContent=on?"♥":"♡";btn.classList.toggle("saved",on);const tag=btn.dataset.outfitTag||id;btn.setAttribute("aria-label",on?`Bỏ lưu ${tag} khỏi Closet`:`Lưu ${tag} vào Closet`)})};window.acApplyOutfitFilters=(_state,matched,count)=>{const was=activeFilterCount>0;activeFilterCount=count||0;activeMatches=Array.isArray(matched)?matched:[];if(activeFilterCount){render(activeMatches);const feed=document.getElementById("feed-end-copy");if(feed)feed.textContent=`Đã hiển thị ${activeMatches.length} outfit phù hợp.`}else if(was)randomize(false)};window.toggleSearch=()=>{const bar=document.getElementById("search-bar"),input=document.getElementById("search-input");if(!bar||!input)return;if(bar.style.display==="block"){if(input.value.trim()){bar.requestSubmit();return}bar.style.display="none"}else{bar.style.display="block";input.focus()}};function init(){syncPool();render(batch(true));const form=document.getElementById("search-bar");form&&form.addEventListener("submit",e=>{const q=document.getElementById("search-input")?.value.trim();if(!q)e.preventDefault()});const audio=document.getElementById("apocalypse-audio"),rec=document.getElementById("record-icon"),player=document.getElementById("music-player");player&&player.addEventListener("click",()=>{if(!audio)return;if(audio.paused){audio.play().catch(()=>{});rec&&rec.classList.add("playing")}else{audio.pause();rec&&rec.classList.remove("playing")}});try{const user=JSON.parse(localStorage.getItem("ac_user")||"null");if(user){const b=document.getElementById("nav-closet-btn"),i=document.getElementById("nav-closet-icon");if(b){b.href="closet.html";b.style.color="#e05444";b.style.borderColor="#c0392b"}if(i)i.textContent="♥"}}catch(e){}window.addEventListener("resize",()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>render(currentData),160)},{passive:true})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init()})();